def ls_rows(out):
    """{key: (open, done, oldest)} from the table body of cmd_ls."""
    lines = out.splitlines()
    body = lines[2:lines.index("-" * 74, 2)]
    rows = {}
    for line in body:
        key, open_, done, oldest = line.split()
        rows[key] = (int(open_), int(done), oldest)
    return rows, [line.split()[0] for line in body]


