class CmdGrepTests(BacklogTestCase):
    def setUp(self):
        super().setUp()
        self.write_index([
            item("mac.local", "zuvo", "B-1", "open", text="Flaky test in CI"),
            item("vps", "Landing-Site", "L-1", "done", text="broken link"),
            item("vps", "api", "A-1", "open", text="slow query"),
        ])

    def test_no_arguments_exits_with_usage(self):
        msg, _o, _e = self.exit_message(self.mod.cmd_grep, [])
        self.assertEqual("usage: backlog grep <text>", msg)

    def test_text_match_is_case_insensitive(self):
        _r, out, _e = self.capture(self.mod.cmd_grep, ["FLAKY"])
        self.assertEqual(["open mac:zuvo B-1 | Flaky test in CI", "", "(1 matches, showing 1)"],
                         out.splitlines())

    def test_repo_match_is_case_insensitive(self):
        _r, out, _e = self.capture(self.mod.cmd_grep, ["landing"])
        self.assertEqual(["done vps:Landing-Site L-1 | broken link", "", "(1 matches, showing 1)"],
                         out.splitlines())

    def test_arguments_are_joined_with_spaces(self):
        # "slow test" contains "test" but not "test in": only the joined phrase may match.
        self.write_index([item("mac.local", "zuvo", "B-1", "open", text="Flaky test in CI"),
                          item("vps", "api", "T-1", "open", text="slow test")])
        _r, out, _e = self.capture(self.mod.cmd_grep, ["test", "in"])
        self.assertEqual(["open mac:zuvo B-1 | Flaky test in CI", "", "(1 matches, showing 1)"],
                         out.splitlines())

    def test_no_match_reports_zero(self):
        _r, out, _e = self.capture(self.mod.cmd_grep, ["zzz"])
        self.assertEqual(["", "(0 matches, showing 0)"], out.splitlines())

    def test_grep_query_spanning_text_and_repo_is_not_a_match(self):
        # Regression (cmd_grep X2): text and repo were concatenated, so "cd" matched text "abc" + repo "def".
        self.write_index([item("h", "def", "S-1", text="abc")])
        _r, out, _e = self.capture(self.mod.cmd_grep, ["cd"])
        self.assertEqual(["", "(0 matches, showing 0)"], out.splitlines())

    def test_grep_matches_either_field_alone(self):
        # `q in text or q in repo`: T-1 matches on text only, R-1 on repo only, N-1 on neither.
        self.write_index([item("h", "alpha", "T-1", text="Needle here"),
                          item("h", "needle-repo", "R-1", text="other"),
                          item("h", "x", "N-1", text="nothing")])
        _r, out, _e = self.capture(self.mod.cmd_grep, ["NEEDLE"])
        self.assertEqual(["T-1", "R-1"], [line.split()[2] for line in out.splitlines() if "|" in line])
        self.assertEqual("(2 matches, showing 2)", out.splitlines()[-1])


