class DispatchTests(BacklogTestCase):
    """`__main__`: the real file as a real process in a sandbox with no collector configured."""

    def setUp(self):
        super().setUp()
        self.write_index([item("mac.local", "zuvo", "B-1", "open", "critical", "2026-01-01", "flaky gate")],
                         meta={"hosts": {"mac.local": {}}, "strays": [{"host": "mac.local", "path": "/wt"}]})

    def test_no_argument_runs_ls(self):
        r = run_cli(self.tmp)
        self.assertEqual(0, r.returncode, r.stderr)
        self.assertIn("mac:zuvo", r.stdout)
        self.assertEqual("TOTAL open=1 done=0 across 1 repos / 1 hosts", r.stdout.splitlines()[-1])

    def test_unknown_command_exits_1_with_usage_on_stderr(self):
        r = run_cli(self.tmp, "nope")
        self.assertEqual(1, r.returncode)
        self.assertTrue(r.stderr.startswith("zuvo backlog — ONE place for every backlog in the fleet"))
        self.assertIn("~/.zuvo/backlog grep <text>       full-text search across every backlog", r.stderr)
        self.assertEqual("", r.stdout)

    def test_grep_without_text_exits_1_with_usage(self):
        r = run_cli(self.tmp, "grep")
        self.assertEqual(1, r.returncode)
        self.assertEqual("usage: backlog grep <text>\n", r.stderr)

    def test_each_view_command_routes_to_its_function(self):
        cases = {
            ("ls",): "TOTAL open=1",
            ("open",): "(1 open, showing 1)",
            ("open", "--repo", "zuvo"): "(1 open in zuvo, showing 1)",
            ("crit",): "(1 critical/high open across the fleet, showing 1)",
            ("grep", "FLAKY"): "(1 matches, showing 1)",
            ("strays",): "  mac: /wt",
        }
        for args, marker in cases.items():
            with self.subTest(args=args):
                r = run_cli(self.tmp, *args)
                self.assertEqual(0, r.returncode, r.stderr)
                self.assertIn(marker, r.stdout)

    def test_pull_and_sync_route_to_the_collector_and_name_the_missing_host(self):
        for cmd, what in (("pull", "pull the fleet index"), ("sync", "fetch the collector token")):
            with self.subTest(cmd=cmd):
                r = run_cli(self.tmp, cmd)
                self.assertEqual(1, r.returncode)
                self.assertEqual("backlog: no collector host configured (ZUVO_COLLECTOR_SSH or "
                                 f"~/.zuvo/collector.conf) — cannot {what}\n", r.stderr)

    def test_argument_count_boundary_no_arg_is_ls_one_arg_is_the_command(self):
        # `len(sys.argv) > 1`: argv of length 1 (equal case) runs ls; length 2 runs the named command.
        r = run_cli(self.tmp)
        self.assertEqual(0, r.returncode, r.stderr)
        self.assertEqual("TOTAL open=1 done=0 across 1 repos / 1 hosts", r.stdout.splitlines()[-1])
        r = run_cli(self.tmp, "strays")
        self.assertEqual(0, r.returncode, r.stderr)
        self.assertEqual(["1 worktree-fork copies (protocol says ONE backlog per repo, "
                          "at the MAIN checkout):", "  mac: /wt"], r.stdout.splitlines())

    def test_missing_index_names_the_script_path(self):
        os.remove(self.mod.INDEX)
        r = run_cli(self.tmp, "ls")
        self.assertEqual(1, r.returncode)
        self.assertIn("no index yet — run: ", r.stderr)
        self.assertIn("scripts/zuvo-home/backlog sync", r.stderr)


class BlindAuditFollowUpViewTests(BacklogTestCase):
    """Rows the blind coverage audit found uncovered or partly covered (pass 1: FIX)."""

    def test_crit_shows_sixty_and_reports_the_true_total(self):
        # Distinct dates, oldest first: C-00 leads and the newest, C-60, is the one cut.
        self.write_index([item("h", "r", f"C-{n:02d}", "open", "critical",
                               f"2026-{n // 28 + 1:02d}-{n % 28 + 1:02d}") for n in range(61)])
        _r, out, _e = self.capture(self.mod.cmd_crit)
        lines = out.splitlines()
        shown = [line.split()[2] for line in lines if line.startswith("CRITICAL ")]
        self.assertEqual(60, len(shown))
        self.assertEqual(("C-00", "C-59"), (shown[0], shown[-1]))
        self.assertNotIn("C-60", shown)
        self.assertEqual("(61 critical/high open across the fleet, showing 60)", lines[-1])

    def test_crit_cuts_text_at_110_characters(self):
        text = "a" * 110 + "TAIL-NOT-SHOWN"
        self.write_index([item("h", "r", "C-1", "open", "high", "2026-01-01", text)])
        _r, out, _e = self.capture(self.mod.cmd_crit)
        self.assertEqual("    HIGH h:r C-1 | " + "a" * 110, out.splitlines()[0])

    def test_grep_shows_sixty_and_reports_the_true_total(self):
        # Index order is kept: G-00..G-59 are shown, G-60 is the one cut.
        self.write_index([item("h", "r", f"G-{n:02d}", text="needle") for n in range(61)])
        _r, out, _e = self.capture(self.mod.cmd_grep, ["needle"])
        lines = out.splitlines()
        shown = [line.split()[2] for line in lines if line.endswith("| needle")]
        self.assertEqual([f"G-{n:02d}" for n in range(60)], shown)
        self.assertEqual("(61 matches, showing 60)", lines[-1])

    def test_grep_tolerates_items_missing_status_text_or_repo(self):
        self.write_index([
            {"host": "h.local", "item_id": "NO-TEXT", "repo": "findme-repo"},
            {"host": "h", "item_id": "NO-REPO", "status": "done", "text": "Findme in text"},
        ])
        _r, out, _e = self.capture(self.mod.cmd_grep, ["FINDME"])
        self.assertEqual(["   ? h:findme-repo NO-TEXT | ", "done h:None NO-REPO | Findme in text", "",
                          "(2 matches, showing 2)"], out.splitlines())


class PolyglotHeaderTests(BacklogTestCase):
    """The file as production runs it: /bin/sh reads the header and re-execs a Python 3."""

    def setUp(self):
        super().setUp()
        self.empty = os.path.join(self.tmp, "empty-bin")
        os.makedirs(self.empty)
        # cmd_open loads the index before it parses --repo; without one it exits "no index yet".
        self.write_index([item("h", "r", "B-1")])

    def run_sh(self, path_dirs, *args):
        env = {"PATH": os.pathsep.join(path_dirs), "HOME": self.tmp,
               "ZUVO_DIR": self.zuvo, "ZUVO_COLLECTOR_SSH": ""}
        # REAL_RUN: the harness patches subprocess.run module-wide for the fake collector.
        return REAL_RUN(["/bin/sh", str(BACKLOG), *args], capture_output=True, text=True,
                        env=env, timeout=60)

    def test_sh_entry_reexecs_python3_and_forwards_argv_and_status(self):
        py_dir = os.path.join(self.tmp, "py3")
        os.makedirs(py_dir)
        os.symlink(os.path.realpath(sys.executable), os.path.join(py_dir, "python3"))
        r = self.run_sh([py_dir, self.empty], "open", "--repo")
        self.assertEqual(2, r.returncode)
        self.assertEqual("backlog open: --repo needs a value\n", r.stderr)
        self.assertEqual("", r.stdout)

    def test_sh_entry_falls_back_to_python_when_python3_is_absent(self):
        py_dir = os.path.join(self.tmp, "py")
        os.makedirs(py_dir)
        os.symlink(os.path.realpath(sys.executable), os.path.join(py_dir, "python"))
        r = self.run_sh([py_dir, self.empty], "open", "--repo")
        self.assertEqual(2, r.returncode)
        self.assertEqual("backlog open: --repo needs a value\n", r.stderr)
        self.assertEqual("", r.stdout)

    def test_sh_entry_with_no_python_at_all_execs_python3_and_fails_not_found(self):
        r = self.run_sh([self.empty], "ls")
        self.assertEqual(127, r.returncode)
        self.assertIn("python3", r.stderr)
        self.assertEqual("", r.stdout)



class FleetDataRobustnessTests(BacklogTestCase):
    """The index is fleet-supplied: unknown statuses and null fields must not break a view."""

    def test_ls_counts_only_open_and_done_and_an_odd_status_cannot_clobber_the_row(self):
        # Regression: the status was used as a dict key on the row, so status "oldest" replaced the
        # oldest date with a count and the next date comparison raised TypeError.
        self.write_index([
            item("h", "r", "A-1", "open", added="2026-02-01"),
            item("h", "r", "A-2", "oldest", added="2026-03-01"),
            item("h", "r", "A-3", "done", added="2026-01-15"),
            item("h", "r", "A-4", "in_progress", added="2026-04-01"),
        ], meta={"hosts": {"h": {}}})
        _r, out, _e = self.capture(self.mod.cmd_ls)
        rows, _order = ls_rows(out)
        self.assertEqual({"h:r": (1, 1, "2026-01-15")}, rows)
        self.assertEqual("TOTAL open=1 done=1 across 1 repos / 1 hosts", out.splitlines()[-1])

    def test_views_survive_null_text_repo_host_and_severity(self):
        # Regression: i.get("text", "") returns None for a key that is present with null, and
        # None.lower() / None[:110] / None.split() raised in grep, open and crit.
        nulls = {"host": None, "repo": None, "item_id": "N-1", "status": "open",
                 "severity": None, "added": None, "text": None}
        crit_null = dict(nulls, item_id="N-2", severity="high")
        self.write_index([nulls, crit_null, item("h", "needle-repo", "R-1", text="plain")])
        _r, out, _e = self.capture(self.mod.cmd_grep, ["needle"])
        self.assertEqual(["open h:needle-repo R-1 | plain", "", "(1 matches, showing 1)"], out.splitlines())
        _r, out, _e = self.capture(self.mod.cmd_open, [])
        self.assertIn("[----------] ?:None N-1        - | ", out.splitlines())
        _r, out, _e = self.capture(self.mod.cmd_open, ["--repo", "needle"])
        self.assertEqual("(1 open in needle, showing 1)", out.splitlines()[-1])
        _r, out, _e = self.capture(self.mod.cmd_crit)
        self.assertEqual(["    HIGH ?:None N-2 | ", "", "(1 critical/high open across the fleet, showing 1)"],
                         out.splitlines())


